describe('Async Operation Cancellation', () => {
    beforeEach(() => {
        cy.visit('/your-page-url'); // Replace with your actual page URL
    });

    it('should complete the async operation when not cancelled', () => {
        cy.get('#start-async-operation').click(); // Replace with the actual button ID
        cy.get('#async-operation-status').should('contain', 'In Progress'); // Check if the operation is in progress
        cy.wait(5000); // Wait for the operation to complete
        cy.get('#async-operation-status').should('contain', 'Completed'); // Check if the operation is completed
    });

    it('should cancel the async operation when the Abort button is clicked', () => {
        cy.get('#start-async-operation').click(); // Start the async operation
        cy.get('#abort-button').click(); // Click the Abort button
        cy.get('#async-operation-status').should('contain', 'Cancelled'); // Check if the operation is cancelled
    });
});
